#!/usr/bin/env bash
# Print the three most frequent client IPs, resolving equal counts by log order.
set -euo pipefail

cd "$(dirname "$0")"

awk '
    NF {
        ip = $1
        if (!(ip in first_seen)) {
            first_seen[ip] = ++seen_count
            order[seen_count] = ip
        }
        count[ip]++
    }
    END {
        for (rank = 1; rank <= 3; rank++) {
            best = ""
            # order[] is in first-appearance order, so only replace on a
            # strictly larger count to preserve that order for ties.
            for (i = 1; i <= seen_count; i++) {
                ip = order[i]
                if (!(ip in selected) && (best == "" || count[ip] > count[best]))
                    best = ip
            }
            if (best == "")
                break
            print best
            selected[best] = 1
        }
    }
' access.log
